<?php

declare(strict_types=1);

namespace PortLibs\LibSqlite;

use InvalidArgumentException;

final class SQLitePragmaIndexXinfoForeignKeyCurrentSourceNext
{

    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param list<array<string,mixed>> $currentForeignKeys
     * @param array<string,list<array<string,mixed>>> $currentTables
     * @param list<SQLiteSchemaRecord> $nextRecords
     * @param list<array<string,mixed>> $nextForeignKeys
     * @param array<string,list<array<string,mixed>>> $nextTables
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array{status:string,source_id:string,current_source:array<string,mixed>,next_source:array<string,mixed>,offset:int,limit:int,count:int,total:int,next_offset:int|null,complete:bool,current:array<string,mixed>,next_counts:array<string,mixed>,delta:array<string,mixed>,next_state:array{ready:bool,blocking:list<string>},next:array{source_id:string,offset:int}|null,rows:list<array<string,mixed>>}
     */
    public static function currentNextPage156(
        array $currentRecords,
        array $currentForeignKeys,
        array $currentTables,
        array $nextRecords,
        array $nextForeignKeys,
        array $nextTables,
        string $indexXinfoSql,
        int $offset = 0,
        int $limit = 156,
        ?array $cursor = null,
        bool $tableValuedIndexXinfo = false,
    ): array {
        if ($offset < 0) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next156 offset must be non-negative');
        }
        if ($limit < 1) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next156 limit must be positive');
        }

        $currentCatalog = new SQLitePragmaSchemaCatalog($currentRecords);
        $nextCatalog = new SQLitePragmaSchemaCatalog($nextRecords);
        $currentSource = self::source156($currentRecords, $currentForeignKeys, $currentTables, $indexXinfoSql, $tableValuedIndexXinfo);
        $nextSource = self::source156($nextRecords, $nextForeignKeys, $nextTables, $indexXinfoSql, $tableValuedIndexXinfo);
        $sourceId = self::stableHash156([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next156',
            'current' => $currentSource['source_id'],
            'next' => $nextSource['source_id'],
        ]);
        if ($cursor !== null) {
            self::validateCursor156($cursor, $sourceId, $offset);
        }

        $currentRows = self::sideRows156('current', self::collect156($currentCatalog, $indexXinfoSql, $currentRecords, $currentForeignKeys, $currentTables, $tableValuedIndexXinfo));
        $nextRows = self::sideRows156('next', self::collect156($nextCatalog, $indexXinfoSql, $nextRecords, $nextForeignKeys, $nextTables, $tableValuedIndexXinfo));
        $rows = [...$currentRows, ...$nextRows];
        $pageRows = array_slice($rows, $offset, $limit);
        $nextOffset = $offset + count($pageRows);
        $complete = $nextOffset >= count($rows);
        $currentCounts = self::counts156($currentRows);
        $nextCounts = self::counts156($nextRows);
        $blocking = self::blocking156($nextCounts);

        return [
            'status' => $blocking === [] ? 'ok' : 'blocked',
            'source_id' => $sourceId,
            'current_source' => self::publicSource156($currentSource),
            'next_source' => self::publicSource156($nextSource),
            'offset' => $offset,
            'limit' => $limit,
            'count' => count($pageRows),
            'total' => count($rows),
            'next_offset' => $complete ? null : $nextOffset,
            'complete' => $complete,
            'current' => $currentCounts,
            'next_counts' => $nextCounts,
            'delta' => [
                'index_xinfo' => $nextCounts['index_xinfo'] - $currentCounts['index_xinfo'],
                'index_admissions' => $nextCounts['index_admissions'] - $currentCounts['index_admissions'],
                'index_blockers' => $nextCounts['index_blockers'] - $currentCounts['index_blockers'],
                'foreign_key_violations' => $nextCounts['foreign_key_violations'] - $currentCounts['foreign_key_violations'],
                'total_blockers' => $nextCounts['total_blockers'] - $currentCounts['total_blockers'],
                'cleared' => $currentCounts['total_blockers'] > 0 && $nextCounts['total_blockers'] === 0,
            ],
            'next_state' => [
                'ready' => $blocking === [],
                'blocking' => $blocking,
            ],
            'next' => $complete ? null : [
                'source_id' => $sourceId,
                'offset' => $nextOffset,
            ],
            'rows' => $pageRows,
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @param list<array<string,mixed>> $foreignKeys
     * @param array<string,list<array<string,mixed>>> $tables
     * @return list<array<string,mixed>>
     */
    public static function collect156(
        SQLitePragmaSchemaCatalog $catalog,
        string $indexXinfoSql,
        array $records,
        array $foreignKeys,
        array $tables,
        bool $tableValuedIndexXinfo = false,
    ): array {
        $indexRows = array_map(
            static fn (array $row): array => [
                ...$row,
                'phase' => 'index_xinfo',
                'source' => 'index_xinfo',
            ],
            SQLitePragmaIndexXinfoIntegrityRootYield::collect($catalog, $indexXinfoSql, '', 'PRAGMA integrity_check', $tableValuedIndexXinfo),
        );
        $indexRows = array_values(array_filter($indexRows, static fn (array $row): bool => ($row['kind'] ?? null) === 'index_xinfo'));

        $foreignKeyRows = array_map(
            static fn (array $row): array => [
                ...$row,
                'phase' => $row['kind'] === 'index_admission' ? 'foreign_key_parent_index' : 'foreign_key_check',
                'source' => $row['kind'] === 'index_admission' ? 'foreign_key_parent_index' : 'foreign_key_check',
            ],
            SQLitePragmaForeignKeyIndexIntegrityYield::collect($records, $foreignKeys, $tables),
        );

        return [...$indexRows, ...$foreignKeyRows];
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<array<string,mixed>>
     */
    private static function sideRows156(string $side, array $rows): array
    {
        return array_map(static fn (array $row): array => ['side' => $side, ...$row], $rows);
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return array<string,mixed>
     */
    private static function counts156(array $rows): array
    {
        $counts = [
            'index_xinfo' => 0,
            'index_admissions' => 0,
            'index_blockers' => 0,
            'foreign_key_violations' => 0,
            'total_blockers' => 0,
            'target_schema' => 'main',
            'target_index' => '',
            'foreign_key_tables' => [],
            'parent_indexes' => [],
        ];

        foreach ($rows as $row) {
            $kind = $row['kind'] ?? null;
            if ($kind === 'index_xinfo') {
                $counts['index_xinfo']++;
                $counts['target_schema'] = (string) ($row['schema'] ?? $counts['target_schema']);
                $counts['target_index'] = (string) ($row['target'] ?? $counts['target_index']);
                continue;
            }
            if ($kind === 'index_admission') {
                $counts['index_admissions']++;
                $table = (string) ($row['table'] ?? '');
                if ($table !== '' && !in_array($table, $counts['foreign_key_tables'], true)) {
                    $counts['foreign_key_tables'][] = $table;
                }
                $index = (string) ($row['index'] ?? '');
                if ($index !== '' && !in_array($index, $counts['parent_indexes'], true)) {
                    $counts['parent_indexes'][] = $index;
                }
                if (($row['status'] ?? 'ok') !== 'ok') {
                    $counts['index_blockers']++;
                    $counts['total_blockers']++;
                }
                continue;
            }
            if ($kind === 'foreign_key_check') {
                $counts['foreign_key_violations']++;
                $counts['total_blockers']++;
            }
        }

        return $counts;
    }

    /**
     * @param array<string,mixed> $counts
     * @return list<string>
     */
    private static function blocking156(array $counts): array
    {
        $blocking = [];
        if (($counts['index_blockers'] ?? 0) > 0) {
            $blocking[] = 'foreign_key_parent_unique_index';
        }
        if (($counts['foreign_key_violations'] ?? 0) > 0) {
            $blocking[] = 'foreign_key_check';
        }

        return $blocking;
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @param list<array<string,mixed>> $foreignKeys
     * @param array<string,list<array<string,mixed>>> $tables
     * @return array<string,mixed>
     */
    private static function source156(array $records, array $foreignKeys, array $tables, string $indexXinfoSql, bool $tableValuedIndexXinfo): array
    {
        $source = [
            'records' => self::stableHash156(self::schemaRecordsSnapshot156($records)),
            'foreign_keys' => self::stableHash156($foreignKeys),
            'tables' => self::stableHash156($tables),
            'index_xinfo_sql' => self::normalizeSql156($indexXinfoSql),
            'table_valued_index_xinfo' => $tableValuedIndexXinfo,
        ];

        return [
            ...$source,
            'source_id' => self::stableHash156($source),
        ];
    }

    /**
     * @param array<string,mixed> $source
     * @return array<string,mixed>
     */
    private static function publicSource156(array $source): array
    {
        return [
            'records' => $source['records'],
            'foreign_keys' => $source['foreign_keys'],
            'tables' => $source['tables'],
            'index_xinfo_sql' => $source['index_xinfo_sql'],
            'table_valued_index_xinfo' => $source['table_valued_index_xinfo'],
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return list<array{type:string,name:string,table:string,rootpage:int|null,sql:string|null,rowid:int}>
     */
    private static function schemaRecordsSnapshot156(array $records): array
    {
        return array_map(
            static function (SQLiteSchemaRecord $record): array {
                if (!$record instanceof SQLiteSchemaRecord) {
                    throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next156 records must be SQLiteSchemaRecord instances');
                }

                return [
                    'type' => $record->type,
                    'name' => $record->name,
                    'table' => $record->tableName,
                    'rootpage' => $record->rootPage,
                    'sql' => $record->sql,
                    'rowid' => $record->rowId,
                ];
            },
            $records,
        );
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor156(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next156 cursor does not match the current source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next156 cursor offset does not match the requested page offset');
        }
    }

    private static function normalizeSql156(string $sql): string
    {
        return strtolower(preg_replace('/\s+/', ' ', rtrim(trim($sql), ';')) ?? trim($sql));
    }

    private static function stableHash156(mixed $value): string
    {
        return hash('sha256', json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES));
    }


    /**
     * @param array<string,array{tables:array<string,list<array<string,mixed>>>,foreignKeys:list<array<string,mixed>>}> $currentSchemas
     * @param array<string,array{tables:array<string,list<array<string,mixed>>>,foreignKeys:list<array<string,mixed>>}> $nextSchemas
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array{status:string,source_id:string,current_source:array<string,mixed>,next_source:array<string,mixed>,offset:int,limit:int,count:int,total:int,next_offset:int|null,complete:bool,current:array<string,mixed>,next_counts:array<string,mixed>,delta:array<string,mixed>,next_state:array{ready:bool,blocking:list<string>},next:array{source_id:string,offset:int}|null,rows:list<array<string,mixed>>}
     */
    public static function currentNextPage157(
        SQLiteAttachedSchemaCatalog|SQLitePragmaSchemaCatalog $currentCatalog,
        string|SQLiteDatabase $currentDatabase,
        array $currentSchemas,
        SQLiteAttachedSchemaCatalog|SQLitePragmaSchemaCatalog $nextCatalog,
        string|SQLiteDatabase $nextDatabase,
        array $nextSchemas,
        string $indexXinfoSql,
        string $foreignKeySql,
        int $offset = 0,
        int $limit = 157,
        string $integritySql = 'PRAGMA integrity_check',
        bool $indexTableValued = false,
        ?array $cursor = null,
        ?SQLiteAttachedSchemaCatalog $currentForeignKeyCatalog = null,
        ?SQLiteAttachedSchemaCatalog $nextForeignKeyCatalog = null,
    ): array {
        if ($offset < 0) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next157 offset must be non-negative');
        }
        if ($limit < 1) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next157 limit must be positive');
        }

        $current = SQLitePragmaIndexIntegrityForeignKeyCurrentSourceYield::page(
            $currentCatalog,
            $indexXinfoSql,
            $currentDatabase,
            $currentSchemas,
            $foreignKeySql,
            0,
            PHP_INT_MAX,
            $integritySql,
            $indexTableValued,
            null,
            $currentForeignKeyCatalog,
        );
        $next = SQLitePragmaIndexIntegrityForeignKeyCurrentSourceYield::page(
            $nextCatalog,
            $indexXinfoSql,
            $nextDatabase,
            $nextSchemas,
            $foreignKeySql,
            0,
            PHP_INT_MAX,
            $integritySql,
            $indexTableValued,
            null,
            $nextForeignKeyCatalog,
        );

        $sourceId = self::stableHash157([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next157',
            'current' => $current['source_id'],
            'next' => $next['source_id'],
        ]);
        if ($cursor !== null) {
            self::validateCursor157($cursor, $sourceId, $offset);
        }

        $currentRows = self::sideRows157('current', $current['rows']);
        $nextRows = self::sideRows157('next', $next['rows']);
        $rows = [...$currentRows, ...$nextRows];
        $pageRows = array_slice($rows, $offset, $limit);
        $nextOffset = $offset + count($pageRows);
        $complete = $nextOffset >= count($rows);
        $currentCounts = self::counts157($currentRows);
        $nextCounts = self::counts157($nextRows);
        $blocking = self::blocking157($nextCounts);

        return [
            'status' => $blocking === [] ? 'ok' : 'blocked',
            'source_id' => $sourceId,
            'current_source' => $current['current_source'],
            'next_source' => $next['current_source'],
            'offset' => $offset,
            'limit' => $limit,
            'count' => count($pageRows),
            'total' => count($rows),
            'next_offset' => $complete ? null : $nextOffset,
            'complete' => $complete,
            'current' => $currentCounts,
            'next_counts' => $nextCounts,
            'delta' => [
                'index_xinfo' => $nextCounts['index_xinfo'] - $currentCounts['index_xinfo'],
                'integrity_root' => $nextCounts['integrity_root'] - $currentCounts['integrity_root'],
                'foreign_key' => $nextCounts['foreign_key'] - $currentCounts['foreign_key'],
                'rootpage_errors' => $nextCounts['rootpage_errors'] - $currentCounts['rootpage_errors'],
                'foreign_key_cleared' => $currentCounts['foreign_key'] > 0 && $nextCounts['foreign_key'] === 0,
                'integrity_cleared' => $currentCounts['rootpage_errors'] > 0 && $nextCounts['rootpage_errors'] === 0,
                'ready' => $blocking === [],
            ],
            'next_state' => [
                'ready' => $blocking === [],
                'blocking' => $blocking,
            ],
            'next' => $complete ? null : [
                'source_id' => $sourceId,
                'offset' => $nextOffset,
            ],
            'rows' => $pageRows,
        ];
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<array<string,mixed>>
     */
    private static function sideRows157(string $side, array $rows): array
    {
        return array_map(static fn (array $row): array => ['side' => $side, ...$row], $rows);
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return array{index_xinfo:int,integrity_root:int,foreign_key:int,rootpage_errors:int,target_schema:string,target_index:string|null,target_table:string|null,foreign_key_tables:list<string>,collations:list<string>,key_columns:int,auxiliary_columns:int,expression_columns:int,rowid_auxiliary:int}
     */
    private static function counts157(array $rows): array
    {
        $counts = [
            'index_xinfo' => 0,
            'integrity_root' => 0,
            'foreign_key' => 0,
            'rootpage_errors' => 0,
            'target_schema' => 'main',
            'target_index' => null,
            'target_table' => null,
            'foreign_key_tables' => [],
            'collations' => [],
            'key_columns' => 0,
            'auxiliary_columns' => 0,
            'expression_columns' => 0,
            'rowid_auxiliary' => 0,
        ];

        foreach ($rows as $row) {
            $kind = (string) ($row['kind'] ?? '');
            if ($kind === 'index_xinfo') {
                $counts['index_xinfo']++;
                $counts['target_schema'] = (string) ($row['schema'] ?? $counts['target_schema']);
                $counts['target_index'] = (string) ($row['target'] ?? $counts['target_index']);
                $counts['target_table'] = (string) ($row['table'] ?? $counts['target_table']);
                $collation = (string) ($row['coll'] ?? 'BINARY');
                if ($collation !== '' && !in_array($collation, $counts['collations'], true)) {
                    $counts['collations'][] = $collation;
                }
                if ((int) ($row['key'] ?? 1) === 1) {
                    $counts['key_columns']++;
                } else {
                    $counts['auxiliary_columns']++;
                }
                if ((int) ($row['cid'] ?? 0) === -2) {
                    $counts['expression_columns']++;
                }
                if ((int) ($row['cid'] ?? 0) === -1) {
                    $counts['rowid_auxiliary']++;
                }
                continue;
            }
            if ($kind === 'foreign_key_check') {
                $counts['foreign_key']++;
                $table = (string) ($row['table'] ?? '');
                if ($table !== '' && !in_array($table, $counts['foreign_key_tables'], true)) {
                    $counts['foreign_key_tables'][] = $table;
                }
                continue;
            }
            $counts['integrity_root']++;
            if (($row['page_status'] ?? 'ok') !== 'ok') {
                $counts['rootpage_errors']++;
            }
        }

        return $counts;
    }

    /**
     * @param array{index_xinfo:int,foreign_key:int,rootpage_errors:int} $counts
     * @return list<string>
     */
    private static function blocking157(array $counts): array
    {
        $blocking = [];
        if ($counts['index_xinfo'] === 0) {
            $blocking[] = 'index_xinfo';
        }
        if ($counts['rootpage_errors'] > 0) {
            $blocking[] = 'index_rootpage_integrity';
        }
        if ($counts['foreign_key'] > 0) {
            $blocking[] = 'foreign_key_check';
        }

        return $blocking;
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor157(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next157 cursor does not match the current/next source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next157 cursor offset does not match the requested page offset');
        }
    }

    private static function stableHash157(mixed $value): string
    {
        return hash('sha256', self::stableEncode157($value));
    }

    private static function stableEncode157(mixed $value): string
    {
        if (is_array($value)) {
            if (!array_is_list($value)) {
                ksort($value);
            }

            return '[' . implode(',', array_map(static fn (mixed $item, string|int $key): string => self::stableEncode157((string) $key) . ':' . self::stableEncode157($item), $value, array_keys($value))) . ']';
        }

        return json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_PRESERVE_ZERO_FRACTION);
    }


