            $foreignKeySql,
            0,
            PHP_INT_MAX,
            $integritySql,
            $indexTableValued,
            null,
            $nextForeignKeyCatalog,
        );
        $sourceId = self::stableHash158([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next158',
            'current' => $currentPage['source_id'],
            'next' => $nextPage['source_id'],
        ]);
        if ($cursor !== null) {
            self::validateCursor158($cursor, $sourceId, $offset);
        }

        $currentRows = self::sideRows158('current', $currentPage['rows']);
        $nextRows = self::sideRows158('next', $nextPage['rows']);
        $rows = [...$currentRows, ...$nextRows];
        $pageRows = array_slice($rows, $offset, $limit);
        $nextOffset = $offset + count($pageRows);
        $complete = $nextOffset >= count($rows);
        $currentCounts = self::counts158($currentRows);
        $nextCounts = self::counts158($nextRows);
        $blocking = self::blocking158($nextCounts);

        return [
            'status' => $blocking === [] ? 'ok' : 'blocked',
            'source_id' => $sourceId,
            'current_source' => $currentPage['current_source'],
            'next_source' => $nextPage['current_source'],
            'offset' => $offset,
