    /**
     * @param list<SQLiteSchemaRecord> $records
     * @param array<string,list<array<string,mixed>>> $tables
     * @return array<string,list<array<string,mixed>>>
     */
    public static function canonicalTables164(array $records, array $tables): array
    {
        $catalog = new SQLitePragmaSchemaCatalog($records);
        $canonical = [];
        foreach ($records as $record) {
            if (!$record instanceof SQLiteSchemaRecord) {
                throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next164 records must be SQLiteSchemaRecord instances');
            }
            if ($record->type !== 'table') {
                continue;
            }

            $rows = self::tableRows164($tables, $record->name);
            $columns = array_map(static fn (array $row): string => (string) $row['name'], $catalog->tableInfo($record->name, true));
            $canonical[$record->name] = array_map(static fn (array $row): array => self::canonicalRow164($row, $columns), $rows);
        }

        foreach ($tables as $name => $rows) {
            if (self::hasTable164($canonical, $name)) {
                continue;
            }
            $canonical[$name] = $rows;
        }

        return $canonical;
    }

    /**
     * @param array<string,list<array<string,mixed>>> $tables
     * @return list<array<string,mixed>>
     */
    private static function tableRows164(array $tables, string $name): array
    {
        if (array_key_exists($name, $tables)) {
            return $tables[$name];
        }
        foreach ($tables as $tableName => $rows) {
            if (strcasecmp($tableName, $name) === 0) {
                return $rows;
            }
        }

        return [];
    }

    /**
     * @param array<string,mixed> $row
     * @param list<string> $columns
     * @return array<string,mixed>
     */
    private static function canonicalRow164(array $row, array $columns): array
    {
        foreach ($columns as $column) {
            if (array_key_exists($column, $row)) {
                continue;
            }
            foreach ($row as $key => $value) {
                if (is_string($key) && strcasecmp($key, $column) === 0) {
                    $row[$column] = $value;
                    break;
                }
            }
        }

        return $row;
    }

    /**
     * @param array<string,list<array<string,mixed>>> $tables
     */
    private static function hasTable164(array $tables, string $name): bool
    {
        foreach (array_keys($tables) as $tableName) {
            if (strcasecmp((string) $tableName, $name) === 0) {
                return true;
            }
        }

        return false;
    }


    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param array<string,list<array<string,mixed>>> $currentTables
     * @param list<SQLiteSchemaRecord> $nextRecords
     * @param array<string,list<array<string,mixed>>> $nextTables
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array<string,mixed>
     */
    public static function currentNextPageFromCatalog165(
        array $currentRecords,
        array $currentTables,
        array $nextRecords,
        array $nextTables,
        string $indexXinfoSql,
        int $offset = 0,
        int $limit = 165,
        ?array $cursor = null,
        bool $tableValuedIndexXinfo = false,
    ): array {
        $currentForeignKeys = self::foreignKeysFromCatalog165($currentRecords);
        $nextForeignKeys = self::foreignKeysFromCatalog165($nextRecords);

        $page = self::currentNextPage156(
            $currentRecords,
            $currentForeignKeys,
            $currentTables,
            $nextRecords,
            $nextForeignKeys,
            $nextTables,
            $indexXinfoSql,
            $offset,
            $limit,
            $cursor,
            $tableValuedIndexXinfo,
        );

        $currentActions = self::actionMap165($currentForeignKeys);
        $nextActions = self::actionMap165($nextForeignKeys);
        $page['rows'] = array_map(
            static function (array $row) use ($currentActions, $nextActions): array {
                if (($row['kind'] ?? null) !== 'index_admission' && ($row['kind'] ?? null) !== 'foreign_key_check') {
                    return $row;
                }

                $map = ($row['side'] ?? 'current') === 'next' ? $nextActions : $currentActions;
                $key = self::actionKey165((string) ($row['table'] ?? ''), (int) ($row['fkid'] ?? -1));
                $action = $map[$key] ?? null;
                if ($action === null) {
                    return $row;
                }

                return [
                    ...$row,
                    'on_update' => $action['on_update'],
                    'on_delete' => $action['on_delete'],
                    'match' => $action['match'],
                    'action_summary' => $action['on_update'] . '/' . $action['on_delete'] . '/' . $action['match'],
                ];
            },
            $page['rows'],
        );

        return [
            ...$page,
            'current_source' => [
                ...$page['current_source'],
                'foreign_key_source' => 'pragma_foreign_key_list',
                'action_source' => 'pragma_foreign_key_list_actions',
                'derived_foreign_keys' => count($currentForeignKeys),
                'action_summary' => self::actionSummary165($currentForeignKeys),
            ],
            'next_source' => [
                ...$page['next_source'],
                'foreign_key_source' => 'pragma_foreign_key_list',
                'action_source' => 'pragma_foreign_key_list_actions',
                'derived_foreign_keys' => count($nextForeignKeys),
                'action_summary' => self::actionSummary165($nextForeignKeys),
            ],
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return list<array<string,mixed>>
     */
    public static function foreignKeysFromCatalog165(array $records): array
    {
        foreach ($records as $record) {
            if (!$record instanceof SQLiteSchemaRecord) {
                throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next165 records must be SQLiteSchemaRecord instances');
            }
        }

        $foreignKeys = self::foreignKeysFromCatalog161($records);
        $actions = self::actionsFromCatalog165($records);

        return array_map(
            static function (array $foreignKey) use ($actions): array {
                $key = self::actionKey165((string) ($foreignKey['table'] ?? ''), (int) ($foreignKey['id'] ?? -1));
                $action = $actions[$key] ?? ['on_update' => 'NO ACTION', 'on_delete' => 'NO ACTION', 'match' => 'NONE'];

                return [
                    ...$foreignKey,
                    'on_update' => $action['on_update'],
                    'on_delete' => $action['on_delete'],
                    'match' => $action['match'],
                ];
            },
            $foreignKeys,
        );
    }

    /**
     * @param list<array<string,mixed>> $foreignKeys
     * @return array<string,array{on_update:string,on_delete:string,match:string}>
     */
    private static function actionMap165(array $foreignKeys): array
    {
        $map = [];
        foreach ($foreignKeys as $foreignKey) {
            $map[self::actionKey165((string) ($foreignKey['table'] ?? ''), (int) ($foreignKey['id'] ?? -1))] = [
                'on_update' => self::action165((string) ($foreignKey['on_update'] ?? 'NO ACTION')),
                'on_delete' => self::action165((string) ($foreignKey['on_delete'] ?? 'NO ACTION')),
                'match' => self::matchName165((string) ($foreignKey['match'] ?? 'NONE')),
            ];
        }

        return $map;
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return array<string,array{on_update:string,on_delete:string,match:string}>
     */
    private static function actionsFromCatalog165(array $records): array
    {
        $catalog = new SQLitePragmaSchemaCatalog($records);
        $actions = [];

        foreach ($records as $record) {
            if (!$record instanceof SQLiteSchemaRecord) {
                throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next165 records must be SQLiteSchemaRecord instances');
            }
            if ($record->type !== 'table') {
                continue;
            }

            foreach ($catalog->execute('PRAGMA foreign_key_list(' . self::pragmaArgumentLiteral165($record->name) . ')')['rows'] as $row) {
                $key = self::actionKey165($record->name, (int) $row['id']);
                $actions[$key] ??= [
                    'on_update' => self::action165((string) $row['on_update']),
                    'on_delete' => self::action165((string) $row['on_delete']),
                    'match' => self::matchName165((string) $row['match']),
                ];
            }
        }

        return $actions;
    }

    /**
     * @param list<array<string,mixed>> $foreignKeys
     * @return array{on_update:array<string,int>,on_delete:array<string,int>,match:array<string,int>}
     */
    private static function actionSummary165(array $foreignKeys): array
    {
        $summary = ['on_update' => [], 'on_delete' => [], 'match' => []];
        foreach ($foreignKeys as $foreignKey) {
            self::increment165($summary['on_update'], self::action165((string) ($foreignKey['on_update'] ?? 'NO ACTION')));
            self::increment165($summary['on_delete'], self::action165((string) ($foreignKey['on_delete'] ?? 'NO ACTION')));
            self::increment165($summary['match'], self::matchName165((string) ($foreignKey['match'] ?? 'NONE')));
        }
        ksort($summary['on_update']);
        ksort($summary['on_delete']);
        ksort($summary['match']);

        return $summary;
    }

    /** @param array<string,int> $counts */
    private static function increment165(array &$counts, string $key): void
    {
        $counts[$key] = ($counts[$key] ?? 0) + 1;
    }

    private static function actionKey165(string $table, int $id): string
    {
        return strtolower($table) . '#' . $id;
    }

    private static function action165(string $action): string
    {
        $normalized = strtoupper(preg_replace('/\s+/', ' ', trim($action)) ?? trim($action));
        return $normalized === '' ? 'NO ACTION' : $normalized;
    }

    private static function matchName165(string $match): string
    {
        $normalized = strtoupper(trim($match));
        return $normalized === '' ? 'NONE' : $normalized;
    }

    private static function pragmaArgumentLiteral165(string $identifier): string
    {
        return "'" . str_replace("'", "''", $identifier) . "'";
    }


    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param array<string,list<array<string,mixed>>> $currentTables
