            $deferrable = ($foreignKey['deferrable'] ?? false) === true;
            $initiallyDeferred = ($foreignKey['initially_deferred'] ?? false) === true;
            if ($deferrable) {
                $summary['deferrable']++;
            }
            if ($initiallyDeferred) {
                $summary['initially_deferred']++;
            }
            if ($deferrable && $initiallyDeferred) {
                $summary['deferred']++;
            } else {
                $summary['immediate']++;
            }
        }

        return $summary;
    }

