    public static function currentNextPageFromCatalog172(
        array $currentRecords,
        array $currentTables,
        array $nextRecords,
        array $nextTables,
        string $indexXinfoSql,
        string $foreignKeySql = 'PRAGMA foreign_key_check',
        int $offset = 0,
        int $limit = 172,
        ?array $cursor = null,
        bool $tableValuedIndexXinfo = false,
    ): array {
        if ($offset < 0) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next172 offset must be non-negative');
        }
        if ($limit < 1) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next172 limit must be positive');
        }

        $currentForeignKeys = self::foreignKeysFromCatalog166($currentRecords);
        $nextForeignKeys = self::foreignKeysFromCatalog166($nextRecords);
        $target = self::foreignKeyTarget172($foreignKeySql);
        $currentCatalog = new SQLitePragmaSchemaCatalog($currentRecords);
        $nextCatalog = new SQLitePragmaSchemaCatalog($nextRecords);

        $currentSource = self::source172($currentRecords, $currentForeignKeys, $currentTables, $indexXinfoSql, $foreignKeySql, $target, $tableValuedIndexXinfo);
        $nextSource = self::source172($nextRecords, $nextForeignKeys, $nextTables, $indexXinfoSql, $foreignKeySql, $target, $tableValuedIndexXinfo);
        $sourceId = self::stableHash172([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next172',
            'current' => $currentSource['source_id'],
            'next' => $nextSource['source_id'],
        ]);
        if ($cursor !== null) {
            self::validateCursor172($cursor, $sourceId, $offset);
        }

        $currentRows = self::sideRows172('current', self::collect172($currentCatalog, $indexXinfoSql, $currentRecords, $currentForeignKeys, $currentTables, $target, $tableValuedIndexXinfo));
        $nextRows = self::sideRows172('next', self::collect172($nextCatalog, $indexXinfoSql, $nextRecords, $nextForeignKeys, $nextTables, $target, $tableValuedIndexXinfo));
        $rows = [...$currentRows, ...$nextRows];
        $pageRows = array_slice($rows, $offset, $limit);
        $nextOffset = $offset + count($pageRows);
        $complete = $nextOffset >= count($rows);
        $currentCounts = self::counts172($currentRows);
        $nextCounts = self::counts172($nextRows);
        $blocking = self::blocking172($nextCounts);

        return [
            'status' => $blocking === [] ? 'ok' : 'blocked',
            'source_id' => $sourceId,
            'current_source' => self::publicSource172($currentSource),
            'next_source' => self::publicSource172($nextSource),
            'offset' => $offset,
            'limit' => $limit,
            'count' => count($pageRows),
            'total' => count($rows),
            'next_offset' => $complete ? null : $nextOffset,
            'complete' => $complete,
            'current' => $currentCounts,
            'next_counts' => $nextCounts,
            'delta' => [
                'index_xinfo' => $nextCounts['index_xinfo'] - $currentCounts['index_xinfo'],
                'index_admissions' => $nextCounts['index_admissions'] - $currentCounts['index_admissions'],
                'index_blockers' => $nextCounts['index_blockers'] - $currentCounts['index_blockers'],
                'foreign_key_violations' => $nextCounts['foreign_key_violations'] - $currentCounts['foreign_key_violations'],
                'total_blockers' => $nextCounts['total_blockers'] - $currentCounts['total_blockers'],
                'cleared' => $currentCounts['total_blockers'] > 0 && $nextCounts['total_blockers'] === 0,
            ],
            'next_state' => [
                'ready' => $blocking === [],
                'blocking' => $blocking,
            ],
            'next' => $complete ? null : [
                'source_id' => $sourceId,
                'offset' => $nextOffset,
            ],
            'rows' => $pageRows,
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @param list<array<string,mixed>> $foreignKeys
     * @param array<string,list<array<string,mixed>>> $tables
     * @return list<array<string,mixed>>
     */
    private static function collect172(
        SQLitePragmaSchemaCatalog $catalog,
        string $indexXinfoSql,
        array $records,
        array $foreignKeys,
        array $tables,
        ?string $target,
        bool $tableValuedIndexXinfo,
    ): array {
        $indexRows = array_map(
            static fn (array $row): array => [
                ...$row,
                'phase' => 'index_xinfo',
                'source' => 'index_xinfo',
            ],
            SQLitePragmaIndexXinfoIntegrityRootYield::collect($catalog, $indexXinfoSql, '', 'PRAGMA integrity_check', $tableValuedIndexXinfo),
        );
        $indexRows = array_values(array_filter($indexRows, static fn (array $row): bool => ($row['kind'] ?? null) === 'index_xinfo'));

        $integrityRows = [];
        foreach (SQLitePragmaForeignKeyIndexIntegrityYield::collect($records, $foreignKeys, $tables) as $row) {
            if ($target !== null && strcasecmp((string) ($row['table'] ?? ''), $target) !== 0) {
                continue;
            }
            if (($row['kind'] ?? null) === 'foreign_key_check') {
                continue;
            }
            $integrityRows[] = [
                ...$row,
                'phase' => 'foreign_key_parent_index',
                'source' => 'foreign_key_parent_index',
            ];
        }

        $violations = array_map(
            static fn (array $row): array => [
                'kind' => 'foreign_key_check',
                'table' => $row['table'],
                'rowid' => $row['rowid'],
                'parent' => $row['parent'],
                'fkid' => $row['fkid'],
                'index' => null,
                'columns' => [],
                'collations' => [],
                'status' => 'violation',
                'message' => "foreign key mismatch in {$row['table']} rowid {$row['rowid']} references {$row['parent']} fkid {$row['fkid']}",
                'phase' => 'foreign_key_check',
                'source' => 'foreign_key_check',
            ],
            SQLitePragmaForeignKeyCheck::check($tables, $foreignKeys, $target),
        );

        return [...$indexRows, ...$integrityRows, ...$violations];
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<array<string,mixed>>
     */
    private static function sideRows172(string $side, array $rows): array
    {
        return array_map(static fn (array $row): array => ['side' => $side, ...$row], $rows);
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return array<string,mixed>
     */
    private static function counts172(array $rows): array
    {
        $counts = [
            'index_xinfo' => 0,
            'index_admissions' => 0,
            'index_blockers' => 0,
            'foreign_key_violations' => 0,
            'total_blockers' => 0,
            'target_schema' => 'main',
            'target_index' => '',
            'foreign_key_tables' => [],
            'parent_indexes' => [],
        ];

        foreach ($rows as $row) {
            $kind = $row['kind'] ?? null;
            if ($kind === 'index_xinfo') {
                $counts['index_xinfo']++;
                $counts['target_schema'] = (string) ($row['schema'] ?? $counts['target_schema']);
                $counts['target_index'] = (string) ($row['target'] ?? $counts['target_index']);
                continue;
            }
            if ($kind === 'index_admission') {
                $counts['index_admissions']++;
                self::appendUnique172($counts['foreign_key_tables'], (string) ($row['table'] ?? ''));
                self::appendUnique172($counts['parent_indexes'], (string) ($row['index'] ?? ''));
                if (($row['status'] ?? 'ok') !== 'ok') {
                    $counts['index_blockers']++;
                    $counts['total_blockers']++;
                }
                continue;
            }
            if ($kind === 'foreign_key_check') {
                $counts['foreign_key_violations']++;
                $counts['total_blockers']++;
                self::appendUnique172($counts['foreign_key_tables'], (string) ($row['table'] ?? ''));
            }
        }

        return $counts;
    }

    /**
     * @param list<string> $values
     */
    private static function appendUnique172(array &$values, string $value): void
    {
        if ($value !== '' && !in_array($value, $values, true)) {
            $values[] = $value;
        }
    }

    /**
     * @param array<string,mixed> $counts
     * @return list<string>
     */
    private static function blocking172(array $counts): array
    {
        $blocking = [];
        if (($counts['index_blockers'] ?? 0) > 0) {
            $blocking[] = 'foreign_key_parent_unique_index';
        }
        if (($counts['foreign_key_violations'] ?? 0) > 0) {
            $blocking[] = 'foreign_key_check';
        }

        return $blocking;
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @param list<array<string,mixed>> $foreignKeys
     * @param array<string,list<array<string,mixed>>> $tables
     * @return array<string,mixed>
     */
    private static function source172(array $records, array $foreignKeys, array $tables, string $indexXinfoSql, string $foreignKeySql, ?string $target, bool $tableValuedIndexXinfo): array
    {
        $source = [
            'records' => self::stableHash172(self::schemaRecordsSnapshot172($records)),
            'foreign_keys' => self::stableHash172($foreignKeys),
            'tables' => self::stableHash172($tables),
            'index_xinfo_sql' => self::normalizeSql172($indexXinfoSql),
            'foreign_key_sql' => self::normalizeSql172($foreignKeySql),
            'foreign_key_target' => $target,
            'table_valued_index_xinfo' => $tableValuedIndexXinfo,
        ];

        return [
            ...$source,
            'source_id' => self::stableHash172($source),
        ];
    }

    /**
     * @param array<string,mixed> $source
     * @return array<string,mixed>
     */
    private static function publicSource172(array $source): array
    {
        return [
            'records' => $source['records'],
            'foreign_keys' => $source['foreign_keys'],
            'tables' => $source['tables'],
            'index_xinfo_sql' => $source['index_xinfo_sql'],
            'foreign_key_sql' => $source['foreign_key_sql'],
            'foreign_key_target' => $source['foreign_key_target'],
            'table_valued_index_xinfo' => $source['table_valued_index_xinfo'],
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return list<array{type:string,name:string,table:string,rootpage:int|null,sql:string|null,rowid:int}>
     */
    private static function schemaRecordsSnapshot172(array $records): array
    {
        return array_map(
            static function (SQLiteSchemaRecord $record): array {
                if (!$record instanceof SQLiteSchemaRecord) {
                    throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next172 records must be SQLiteSchemaRecord instances');
                }

                return [
                    'type' => $record->type,
                    'name' => $record->name,
                    'table' => $record->tableName,
                    'rootpage' => $record->rootPage,
                    'sql' => $record->sql,
                    'rowid' => $record->rowId,
                ];
            },
            $records,
        );
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor172(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next172 cursor does not match the current/next source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next172 cursor offset does not match the requested page offset');
        }
    }

    private static function foreignKeyTarget172(string $foreignKeySql): ?string
    {
        $emptyTables = [];
        $emptyKeys = [];
        return SQLitePragmaForeignKeyCheck::execute($foreignKeySql, $emptyTables, $emptyKeys)['target'];
    }

    private static function normalizeSql172(string $sql): string
    {
        return strtolower(preg_replace('/\s+/', ' ', rtrim(trim($sql), ';')) ?? trim($sql));
    }

    private static function stableHash172(mixed $value): string
    {
        return hash('sha256', json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES));
    }


    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param array<string,list<array<string,mixed>>> $currentTables
     * @param list<SQLiteSchemaRecord> $nextRecords
     * @param array<string,list<array<string,mixed>>> $nextTables
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array<string,mixed>
     */
    public static function currentNextPageFromCatalog173(
        array $currentRecords,
        array $currentTables,
        array $nextRecords,
        array $nextTables,
        string $indexXinfoSql,
        int $offset = 0,
        int $limit = 173,
        ?array $cursor = null,
        bool $tableValuedIndexXinfo = false,
    ): array {
        $page = self::currentNextPageFromCatalog167(
            $currentRecords,
            $currentTables,
            $nextRecords,
            $nextTables,
            $indexXinfoSql,
            $offset,
            $limit,
            null,
            $tableValuedIndexXinfo,
        );

        $currentDeferrals = self::deferralRows173($currentRecords);
        $nextDeferrals = self::deferralRows173($nextRecords);
        $sourceId = self::stableHash173([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next173',
            'base' => $page['source_id'],
            'current_deferrals' => self::deferralSummary173($currentDeferrals),
            'next_deferrals' => self::deferralSummary173($nextDeferrals),
        ]);
        if ($cursor !== null) {
            self::validateCursor173($cursor, $sourceId, $offset);
        }

        $currentMap = self::deferralMap173($currentDeferrals);
        $nextMap = self::deferralMap173($nextDeferrals);

        return [
            ...$page,
            'source_id' => $sourceId,
            'current_source' => [
                ...$page['current_source'],
                'foreign_key_deferral_source' => 'create_table_foreign_key_clause',
                'foreign_key_deferrals' => self::deferralSummary173($currentDeferrals),
            ],
            'next_source' => [
                ...$page['next_source'],
                'foreign_key_deferral_source' => 'create_table_foreign_key_clause',
                'foreign_key_deferrals' => self::deferralSummary173($nextDeferrals),
            ],
            'current' => [
                ...$page['current'],
                'foreign_key_deferrals' => self::deferralCounts173($currentDeferrals),
            ],
            'next_counts' => [
                ...$page['next_counts'],
                'foreign_key_deferrals' => self::deferralCounts173($nextDeferrals),
            ],
            'delta' => [
                ...$page['delta'],
                'foreign_key_deferral_changes' => self::deferralChangeCount173($currentDeferrals, $nextDeferrals),
                'foreign_key_deferral_changed' => self::deferralSummary173($currentDeferrals) !== self::deferralSummary173($nextDeferrals),
            ],
            'next' => $page['next'] === null ? null : [
                'source_id' => $sourceId,
                'offset' => $page['next']['offset'],
            ],
            'rows' => array_map(
                static fn (array $row): array => self::decorateRow173($row, ($row['side'] ?? 'current') === 'next' ? $nextMap : $currentMap),
                $page['rows'],
            ),
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}>
     */
    public static function deferralRows173(array $records): array
    {
        $rows = [];
        foreach ($records as $record) {
            if (!$record instanceof SQLiteSchemaRecord) {
                throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next173 records must be SQLiteSchemaRecord instances');
            }
            if ($record->type !== 'table' || $record->sql === null) {
                continue;
            }

            $foreignKeys = self::foreignKeyClauses173($record->sql);
            foreach ($foreignKeys as $id => $clause) {
                $rows[] = [
                    'table' => $record->name,
                    'fkid' => $id,
                    'deferred' => self::isDeferred173($clause),
                    'initially' => self::initially173($clause),
                    'deferrable' => self::deferrable173($clause),
                ];
            }
        }

        return $rows;
    }

    /**
     * @param list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}> $deferrals
     * @return list<string>
     */
    private static function deferralSummary173(array $deferrals): array
    {
        $summary = array_map(
            static fn (array $row): string => $row['table'] . '#' . $row['fkid'] . ':' . $row['deferrable'] . ',initially=' . $row['initially'],
            $deferrals,
        );
        sort($summary);

        return $summary;
    }

    /**
     * @param list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}> $deferrals
     * @return array<string,int>
     */
    private static function deferralCounts173(array $deferrals): array
    {
        $counts = [
            'deferrable' => 0,
            'not_deferrable' => 0,
            'initially_deferred' => 0,
            'initially_immediate' => 0,
            'deferred_runtime' => 0,
        ];
        foreach ($deferrals as $row) {
            if ($row['deferrable'] === 'DEFERRABLE') {
                $counts['deferrable']++;
            } else {
                $counts['not_deferrable']++;
            }
            if ($row['initially'] === 'DEFERRED') {
                $counts['initially_deferred']++;
            } else {
                $counts['initially_immediate']++;
            }
            if ($row['deferred']) {
                $counts['deferred_runtime']++;
            }
        }

        return $counts;
    }

    /**
     * @param list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}> $deferrals
     * @return array<string,array{deferred:bool,initially:string,deferrable:string}>
     */
    private static function deferralMap173(array $deferrals): array
    {
        $map = [];
        foreach ($deferrals as $row) {
            $map[self::deferralKey173($row['table'], $row['fkid'])] = [
                'deferred' => $row['deferred'],
                'initially' => $row['initially'],
                'deferrable' => $row['deferrable'],
            ];
        }

        return $map;
    }

    /**
     * @param array<string,array{deferred:bool,initially:string,deferrable:string}> $deferrals
     * @return array<string,mixed>
     */
    private static function decorateRow173(array $row, array $deferrals): array
    {
        if (($row['kind'] ?? null) !== 'index_admission' && ($row['kind'] ?? null) !== 'foreign_key_check') {
            return $row;
        }

        $deferral = $deferrals[self::deferralKey173((string) ($row['table'] ?? ''), (int) ($row['fkid'] ?? -1))] ?? null;
        if ($deferral === null) {
            return $row;
        }

        return [
            ...$row,
            'deferrable' => $deferral['deferrable'],
            'initially' => $deferral['initially'],
            'deferred' => $deferral['deferred'],
            'deferral_summary' => $deferral['deferrable'] . '/INITIALLY ' . $deferral['initially'],
        ];
    }

    /**
     * @param list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}> $current
     * @param list<array{table:string,fkid:int,deferred:bool,initially:string,deferrable:string}> $next
     */
    private static function deferralChangeCount173(array $current, array $next): int
    {
        return count(array_diff(self::deferralSummary173($next), self::deferralSummary173($current)))
            + count(array_diff(self::deferralSummary173($current), self::deferralSummary173($next)));
    }

    /**
     * @return list<string>
     */
    private static function foreignKeyClauses173(string $sql): array
    {
        $body = self::parenthesizedBody173($sql);
        if ($body === null) {
            return [];
        }

        $clauses = [];
        foreach (self::splitTopLevel173($body, ',') as $definition) {
            $definition = trim($definition);
            if (preg_match('/^(?:CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\s+)?FOREIGN\s+KEY\b/is', $definition) === 1) {
                $clauses[] = $definition;
                continue;
            }
            if (preg_match('/^(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\b.*\bREFERENCES\b/is', $definition) === 1) {
                $clauses[] = $definition;
            }
        }

        return $clauses;
    }

    private static function isDeferred173(string $clause): bool
    {
        return preg_match('/\bDEFERRABLE\s+INITIALLY\s+DEFERRED\b/i', $clause) === 1;
    }

    private static function initially173(string $clause): string
    {
        if (preg_match('/\bINITIALLY\s+DEFERRED\b/i', $clause) === 1) {
            return 'DEFERRED';
        }

        return 'IMMEDIATE';
    }

    private static function deferrable173(string $clause): string
    {
        if (preg_match('/\bNOT\s+DEFERRABLE\b/i', $clause) === 1) {
            return 'NOT DEFERRABLE';
        }
        if (preg_match('/\bDEFERRABLE\b/i', $clause) === 1) {
            return 'DEFERRABLE';
        }

        return 'NOT DEFERRABLE';
    }

    private static function deferralKey173(string $table, int $id): string
    {
        return strtolower($table) . '#' . $id;
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor173(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next173 cursor does not match the current source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next173 cursor offset does not match the requested page offset');
        }
    }

    private static function parenthesizedBody173(string $sql): ?string
    {
        $open = strpos($sql, '(');
        if ($open === false) {
            return null;
        }
        $depth = 0;
        $quote = null;
        $length = strlen($sql);
        for ($i = $open; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if (($quote === "'" || $quote === '"') && ($sql[$i + 1] ?? '') === $quote) {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
            } elseif ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return substr($sql, $open + 1, $i - $open - 1);
                }
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel173(string $value, string $delimiter): array
    {
        $parts = [];
        $start = 0;
        $depth = 0;
        $quote = null;
        $length = strlen($value);

        for ($i = 0; $i < $length; $i++) {
            $char = $value[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if (($quote === "'" || $quote === '"') && ($value[$i + 1] ?? '') === $quote) {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                continue;
            }
            if ($char === $delimiter && $depth === 0) {
                $parts[] = substr($value, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $parts[] = substr($value, $start);

        return $parts;
    }

    private static function stableHash173(mixed $value): string
    {
        return hash('sha256', json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES));
    }


    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param array<string,list<array<string,mixed>>> $currentTables
     * @param list<SQLiteSchemaRecord> $nextRecords
     * @param array<string,list<array<string,mixed>>> $nextTables
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array<string,mixed>
     */
    public static function currentNextPageFromCatalog175(
        array $currentRecords,
        array $currentTables,
