                $counts['unnamed']++;
            } else {
                $counts['named']++;
            }
            if ($row['origin'] === 'table') {
                $counts['table_origin']++;
            } else {
                $counts['column_origin']++;
            }
            if (count($row['child_columns']) > 1) {
                $counts['composite_child_keys']++;
            }
        }

        return $counts;
    }

    /**
     * @param list<array{table:string,fkid:int,constraint_name:string|null,origin:string,child_columns:list<string>,parent_table:string|null}> $constraints
     * @return array<string,array{constraint_name:string|null,origin:string,child_columns:list<string>,parent_table:string|null,constraint_summary:string}>
     */
    private static function constraintMap177(array $constraints): array
    {
        $map = [];
        foreach ($constraints as $row) {
            $name = $row['constraint_name'];
            $map[self::constraintKey177($row['table'], $row['fkid'])] = [
                'constraint_name' => $name,
                'origin' => $row['origin'],
                'child_columns' => $row['child_columns'],
                'parent_table' => $row['parent_table'],
                'constraint_summary' => ($name ?? '<unnamed>') . '/' . $row['origin'] . '/' . implode(',', $row['child_columns']),
            ];
        }

        return $map;
    }

    /**
     * @param array<string,array{constraint_name:string|null,origin:string,child_columns:list<string>,parent_table:string|null,constraint_summary:string}> $constraints
     * @return array<string,mixed>
     */
    private static function decorateRow177(array $row, array $constraints): array
    {
        if (($row['kind'] ?? null) !== 'index_admission' && ($row['kind'] ?? null) !== 'foreign_key_check') {
            return $row;
        }

        $constraint = $constraints[self::constraintKey177((string) ($row['table'] ?? ''), (int) ($row['fkid'] ?? -1))] ?? null;
        if ($constraint === null) {
            return $row;
        }

        return [
            ...$row,
            'constraint_name' => $constraint['constraint_name'],
            'constraint_origin' => $constraint['origin'],
            'constraint_child_columns' => $constraint['child_columns'],
            'constraint_parent_table' => $constraint['parent_table'],
            'constraint_summary' => $constraint['constraint_summary'],
        ];
    }

    /**
     * @param list<array{table:string,fkid:int,constraint_name:string|null,origin:string,child_columns:list<string>,parent_table:string|null}> $current
     * @param list<array{table:string,fkid:int,constraint_name:string|null,origin:string,child_columns:list<string>,parent_table:string|null}> $next
     */
    private static function constraintChangeCount177(array $current, array $next): int
    {
        return count(array_diff(self::constraintSummary177($next), self::constraintSummary177($current)))
            + count(array_diff(self::constraintSummary177($current), self::constraintSummary177($next)));
    }

    /**
     * @return list<string>
     */
    private static function foreignKeyClauses177(string $sql): array
    {
        $body = self::parenthesizedBody177($sql);
        if ($body === null) {
            return [];
        }

        $clauses = [];
        foreach (self::splitTopLevel177($body, ',') as $definition) {
            $definition = trim($definition);
            if (preg_match('/^(?:CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\s+)?FOREIGN\s+KEY\b/is', $definition) === 1) {
                $clauses[] = $definition;
                continue;
            }
            if (preg_match('/^(?:CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\s+)?(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\b.*\bREFERENCES\b/is', $definition) === 1) {
                $clauses[] = $definition;
            }
        }

        return $clauses;
    }

    private static function constraintName177(string $clause): ?string
    {
        $clause = trim($clause);
        if (preg_match('/^CONSTRAINT\s+(?:"(?<dq>(?:""|[^"])*)"|`(?<bt>[^`]*)`|\[(?<br>[^\]]*)\]|(?<bare>[A-Za-z_][A-Za-z0-9_]*))/is', $clause, $matches) === 1) {
            return self::identifierFromMatch177($matches);
        }
        if (preg_match('/^(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\b.*?\bCONSTRAINT\s+(?:"(?<dq>(?:""|[^"])*)"|`(?<bt>[^`]*)`|\[(?<br>[^\]]*)\]|(?<bare>[A-Za-z_][A-Za-z0-9_]*))\s+REFERENCES\b/is', $clause, $matches) === 1) {
            return self::identifierFromMatch177($matches);
        }

        return null;
    }

    private static function constraintOrigin177(string $clause): string
    {
        $clause = trim((string) preg_replace('/^CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\s+/is', '', trim($clause)));

        return preg_match('/^FOREIGN\s+KEY\b/i', $clause) === 1 ? 'table' : 'column';
    }

    /**
     * @return list<string>
     */
    private static function childColumns177(string $clause): array
    {
        $trimmed = trim((string) preg_replace('/^CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\s+/is', '', trim($clause)));
        if (preg_match('/^FOREIGN\s+KEY\s*\((?<cols>.*)\)\s+REFERENCES\b/is', $trimmed, $matches) === 1) {
            return array_map(self::normalizeIdentifier177(...), self::splitTopLevel177($matches['cols'], ','));
        }
        if (preg_match('/^(?<col>"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)\b/is', $trimmed, $matches) === 1) {
            return [self::normalizeIdentifier177($matches['col'])];
        }

        return [];
    }

    private static function parentTable177(string $clause): ?string
    {
        if (preg_match('/\bREFERENCES\s+(?<table>"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)/is', $clause, $matches) !== 1) {
            return null;
        }

        return self::normalizeIdentifier177($matches['table']);
    }

    private static function normalizeIdentifier177(string $identifier): string
    {
        $identifier = trim($identifier);
        if ($identifier === '') {
            return '';
        }
        $first = $identifier[0];
        $last = $identifier[strlen($identifier) - 1];
        if (($first === '"' && $last === '"') || ($first === '`' && $last === '`')) {
            return str_replace($first . $first, $first, substr($identifier, 1, -1));
        }
        if ($first === '[' && $last === ']') {
            return substr($identifier, 1, -1);
        }

        return $identifier;
    }

    /**
     * @param array<string,string> $matches
     */
    private static function identifierFromMatch177(array $matches): string
    {
        return str_replace('""', '"', $matches['dq'] ?: ($matches['bt'] ?: ($matches['br'] ?: $matches['bare'])));
    }

    private static function constraintKey177(string $table, int $id): string
    {
        return strtolower($table) . '#' . $id;
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor177(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next177 cursor does not match the current source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next177 cursor offset does not match the requested page offset');
        }
    }

    private static function parenthesizedBody177(string $sql): ?string
    {
        $open = strpos($sql, '(');
        if ($open === false) {
            return null;
        }
        $depth = 0;
        $quote = null;
        $length = strlen($sql);
        for ($i = $open; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if (($quote === "'" || $quote === '"') && ($sql[$i + 1] ?? '') === $quote) {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return substr($sql, $open + 1, $i - $open - 1);
                }
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel177(string $value, string $delimiter): array
    {
        $parts = [];
        $start = 0;
        $depth = 0;
        $quote = null;
        $length = strlen($value);
        for ($i = 0; $i < $length; $i++) {
            $char = $value[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if (($quote === "'" || $quote === '"') && ($value[$i + 1] ?? '') === $quote) {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                continue;
            }
            if ($char === $delimiter && $depth === 0) {
                $parts[] = substr($value, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $parts[] = substr($value, $start);

        return $parts;
    }

    private static function stableHash177(mixed $value): string
    {
        return hash('sha256', json_encode($value, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES));
    }


    /**
     * @param list<SQLiteSchemaRecord> $currentRecords
     * @param array<string,list<array<string,mixed>>> $currentTables
     * @param list<SQLiteSchemaRecord> $nextRecords
     * @param array<string,list<array<string,mixed>>> $nextTables
     * @param array{source_id?:string,next_offset?:int|null,offset?:int|null}|null $cursor
     * @return array<string,mixed>
     */
    public static function currentNextPageFromCatalog178(
        array $currentRecords,
        array $currentTables,
        array $nextRecords,
        array $nextTables,
        string $indexXinfoSql,
        int $offset = 0,
        int $limit = 178,
        ?array $cursor = null,
        bool $tableValuedIndexXinfo = false,
    ): array {
        if ($offset < 0) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next178 offset must be non-negative');
        }
        if ($limit <= 0) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next178 limit must be positive');
        }

        $base = self::currentNextPageFromCatalog175(
            $currentRecords,
            $currentTables,
            $nextRecords,
            $nextTables,
            $indexXinfoSql,
            0,
            PHP_INT_MAX,
            null,
            $tableValuedIndexXinfo,
        );

        $currentRows = self::parentKeyRows178($currentRecords, 'current');
        $nextRows = self::parentKeyRows178($nextRecords, 'next');
        $allRows = array_values(array_merge($base['rows'], $currentRows, $nextRows));
        $sourceId = self::stableHash178([
            'mode' => 'pragma-index-xinfo-foreignkey-current-source-next178',
            'base' => $base['source_id'],
            'current_parent_key_rows' => self::rowSummary178($currentRows),
            'next_parent_key_rows' => self::rowSummary178($nextRows),
        ]);

        if ($cursor !== null) {
            self::validateCursor178($cursor, $sourceId, $offset);
        }

        $total = count($allRows);
        $rows = array_slice($allRows, $offset, $limit);
        $nextOffset = $offset + count($rows);
        $complete = $nextOffset >= $total;

        return [
            ...$base,
            'source_id' => $sourceId,
            'offset' => $offset,
            'limit' => $limit,
            'count' => count($rows),
            'total' => $total,
            'next_offset' => $complete ? null : $nextOffset,
            'complete' => $complete,
            'current_source' => [
                ...$base['current_source'],
                'foreign_key_parent_key_source' => 'pragma_index_xinfo_parent_key_columns',
                'foreign_key_parent_key_rows' => count($currentRows),
            ],
            'next_source' => [
                ...$base['next_source'],
                'foreign_key_parent_key_source' => 'pragma_index_xinfo_parent_key_columns',
                'foreign_key_parent_key_rows' => count($nextRows),
            ],
            'current' => [
                ...$base['current'],
                'foreign_key_parent_key_rows' => count($currentRows),
                'foreign_key_parent_key_columns' => self::columnCounts178($currentRows),
            ],
            'next_counts' => [
                ...$base['next_counts'],
                'foreign_key_parent_key_rows' => count($nextRows),
                'foreign_key_parent_key_columns' => self::columnCounts178($nextRows),
            ],
            'delta' => [
                ...$base['delta'],
                'foreign_key_parent_key_rows' => count($nextRows) - count($currentRows),
                'foreign_key_parent_key_changed' => self::rowSummary178($currentRows, false) !== self::rowSummary178($nextRows, false),
            ],
            'next' => $complete ? null : [
                'source_id' => $sourceId,
                'offset' => $nextOffset,
            ],
            'rows' => $rows,
        ];
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return list<array<string,mixed>>
     */
    public static function parentKeyRows178(array $records, string $side = 'current'): array
    {
        foreach ($records as $record) {
            if (!$record instanceof SQLiteSchemaRecord) {
                throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next178 records must be SQLiteSchemaRecord instances');
            }
        }

        $catalog = new SQLitePragmaSchemaCatalog($records);
        $rows = [];
        foreach (self::groupForeignKeyRows178(self::foreignKeyListRows175($records, $side)) as $group) {
            $parent = (string) $group[0]['parent'];
            $parentColumns = array_map(static fn (array $row): string => (string) $row['to'], $group);
            $candidate = self::matchingParentIndex178($catalog, $parent, $parentColumns);

            foreach ($group as $row) {
                $indexRow = $candidate['rows'][(int) $row['seq']] ?? null;
                $rows[] = [
                    'side' => $side,
                    'kind' => 'foreign_key_parent_key',
                    'table' => (string) $row['table'],
                    'fkid' => (int) $row['id'],
                    'seq' => (int) $row['seq'],
                    'parent' => $parent,
                    'from' => (string) $row['from'],
                    'to' => (string) $row['to'],
                    'index' => $candidate['name'],
                    'index_seqno' => $indexRow['seqno'] ?? null,
                    'index_cid' => $indexRow['cid'] ?? null,
                    'index_name' => $indexRow['name'] ?? null,
                    'index_coll' => $indexRow['coll'] ?? null,
                    'index_key' => $indexRow['key'] ?? null,
                    'auxiliary_columns_ignored' => $candidate['auxiliary_columns'],
                    'status' => $candidate['name'] === null ? 'missing_parent_key' : 'ok',
                    'message' => $candidate['name'] === null
                        ? "foreign key {$row['table']}->{$parent} parent columns are not backed by PRAGMA index_xinfo key columns"
                        : "foreign key {$row['table']}->{$parent} column {$row['to']} maps to {$candidate['name']} key {$row['seq']}",
                ];
            }
        }

        usort(
            $rows,
            static fn (array $left, array $right): int => [$left['side'], $left['table'], $left['fkid'], $left['seq']]
                <=> [$right['side'], $right['table'], $right['fkid'], $right['seq']],
        );

        return $rows;
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<list<array<string,mixed>>>
     */
    private static function groupForeignKeyRows178(array $rows): array
    {
        $groups = [];
        foreach ($rows as $row) {
            $key = strtolower((string) $row['table']) . '#' . (int) $row['id'];
            $groups[$key][] = $row;
        }

        foreach ($groups as &$group) {
            usort($group, static fn (array $left, array $right): int => (int) $left['seq'] <=> (int) $right['seq']);
        }

        return array_values($groups);
    }

    /**
     * @param list<string> $parentColumns
     * @return array{name:string|null,rows:list<array<string,mixed>>,auxiliary_columns:int}
     */
    private static function matchingParentIndex178(SQLitePragmaSchemaCatalog $catalog, string $parent, array $parentColumns): array
    {
        foreach ($catalog->execute('PRAGMA index_list(' . self::pragmaArgumentLiteral178($parent) . ')')['rows'] as $index) {
            if ((int) $index['unique'] !== 1 || (int) $index['partial'] !== 0) {
                continue;
            }

            $indexName = (string) $index['name'];
            $xinfo = $catalog->execute('PRAGMA index_xinfo(' . self::pragmaArgumentLiteral178($indexName) . ')')['rows'];
            $keyRows = array_values(array_filter($xinfo, static fn (array $row): bool => (int) ($row['key'] ?? 0) === 1));
            $indexColumns = array_map(static fn (array $row): string => strtolower((string) ($row['name'] ?? '')), $keyRows);
            if ($indexColumns !== array_map('strtolower', $parentColumns)) {
                continue;
            }

            return [
                'name' => $indexName,
                'rows' => $keyRows,
                'auxiliary_columns' => count($xinfo) - count($keyRows),
            ];
        }

        $rowid = self::rowidAliasRows178($catalog, $parent, $parentColumns);
        if ($rowid !== []) {
            return [
                'name' => 'rowid-primary-key',
                'rows' => $rowid,
                'auxiliary_columns' => 0,
            ];
        }

        return [
            'name' => null,
            'rows' => [],
            'auxiliary_columns' => 0,
        ];
    }

    /**
     * @param list<string> $parentColumns
     * @return list<array<string,mixed>>
     */
    private static function rowidAliasRows178(SQLitePragmaSchemaCatalog $catalog, string $parent, array $parentColumns): array
    {
        if (count($parentColumns) !== 1) {
            return [];
        }

        foreach ($catalog->execute('PRAGMA table_info(' . self::pragmaArgumentLiteral178($parent) . ')')['rows'] as $row) {
            if (strcasecmp((string) $row['name'], $parentColumns[0]) === 0 && (int) $row['pk'] === 1 && strtoupper((string) $row['type']) === 'INTEGER') {
                return [[
                    'seqno' => 0,
                    'cid' => $row['cid'],
                    'name' => $row['name'],
                    'coll' => 'BINARY',
                    'key' => 1,
                ]];
            }
        }

        return [];
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return array<string,int>
     */
    private static function columnCounts178(array $rows): array
    {
        $counts = [
            'rows' => count($rows),
            'mapped' => 0,
            'missing_parent_key' => 0,
            'rowid_parent_key' => 0,
            'auxiliary_columns_ignored' => 0,
        ];
        foreach ($rows as $row) {
            if (($row['status'] ?? null) === 'ok') {
                $counts['mapped']++;
            } else {
                $counts['missing_parent_key']++;
            }
            if (($row['index'] ?? null) === 'rowid-primary-key') {
                $counts['rowid_parent_key']++;
            }
            $counts['auxiliary_columns_ignored'] += (int) ($row['auxiliary_columns_ignored'] ?? 0);
        }

        return $counts;
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<string>
     */
    private static function rowSummary178(array $rows, bool $includeSide = true): array
    {
        $summary = array_map(
            static fn (array $row): string => ($includeSide ? $row['side'] . ':' : '') . $row['table'] . '#' . $row['fkid'] . '.' . $row['seq'] . ':' . $row['from'] . '->' . $row['parent'] . '.' . $row['to'] . ':' . ($row['index'] ?? '') . ':' . ($row['index_key'] ?? ''),
            $rows,
        );
        sort($summary);

        return $summary;
    }

    /**
     * @param array<string,mixed> $cursor
     */
    private static function validateCursor178(array $cursor, string $sourceId, int $offset): void
    {
        if (($cursor['source_id'] ?? null) !== $sourceId) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next178 cursor does not match the current source');
        }
        $cursorOffset = $cursor['next_offset'] ?? $cursor['offset'] ?? null;
        if ($cursorOffset !== null && $cursorOffset !== $offset) {
            throw new InvalidArgumentException('SQLite PRAGMA index_xinfo/FK current-source next178 cursor offset does not match the requested page offset');
        }
    }

    private static function pragmaArgumentLiteral178(string $value): string
    {
        return "'" . str_replace("'", "''", $value) . "'";
