    private static function declaredColumnCollation205(string $createTableSql, string $columnName): string
    {
        $open = strpos($createTableSql, '(');
        $close = $open === false ? false : strrpos($createTableSql, ')');
        if ($open === false || $close === false || $close <= $open) {
            return 'BINARY';
        }
        foreach (self::splitTopLevel205(substr($createTableSql, $open + 1, $close - $open - 1), ',') as $definition) {
            $definition = trim($definition);
            if ($definition === '') {
                continue;
            }
            if (!preg_match('/^(?:"(?<dq>(?:""|[^"])*)"|`(?<bt>[^`]*)`|\[(?<br>[^\]]*)\]|(?<bare>[A-Za-z_][A-Za-z0-9_]*))(?<tail>.*)$/s', $definition, $matches)) {
                continue;
            }
            $name = $matches['bare'] !== '' ? $matches['bare'] : (($matches['dq'] ?? '') !== '' ? str_replace('""', '"', $matches['dq']) : (($matches['bt'] ?? '') !== '' ? $matches['bt'] : ($matches['br'] ?? '')));
            if (strcasecmp($name, $columnName) !== 0) {
                continue;
            }
            if (!preg_match('/\bCOLLATE\s+(?:"(?<cdq>(?:""|[^"])*)"|`(?<cbt>[^`]*)`|\[(?<cbr>[^\]]*)\]|(?<cbare>[A-Za-z_][A-Za-z0-9_]*))/i', (string) ($matches['tail'] ?? ''), $collation)) {
                return 'BINARY';
            }
            foreach (['cbare', 'cdq', 'cbt', 'cbr'] as $key) {
                if (($collation[$key] ?? '') !== '') {
                    return strtoupper(str_replace('""', '"', $collation[$key]));
                }
            }
        }

        return 'BINARY';
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel205(string $value, string $delimiter): array
    {
        $parts = [];
        $start = 0;
        $depth = 0;
        $quote = null;
        $length = strlen($value);
        for ($i = 0; $i < $length; $i++) {
            $char = $value[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if ($quote === '"' && ($value[$i + 1] ?? null) === '"') {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === '"' || $char === "'" || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth = max(0, $depth - 1);
                continue;
            }
            if ($depth === 0 && $char === $delimiter) {
                $parts[] = substr($value, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $parts[] = substr($value, $start);

        return $parts;
    }

