            if (($row['ascending_prefix'] ?? true) === false) {
                $counts['descending_prefix']++;
            }
            if (($row['child_index_partial'] ?? null) === 1) {
                $counts['partial_index']++;
            }
            $counts['extra_key_columns'] += (int) ($row['extra_key_columns'] ?? 0);
