            foreach ($groups as $id => $foreignKeyRows) {
                usort($foreignKeyRows, static fn (array $left, array $right): int => (int) $left['seq'] <=> (int) $right['seq']);
                $parent = (string) $foreignKeyRows[0]['table'];
                $hasImplicitParent = false;
