    public static function setDefaultChildRows210(array $records, string $phase = 'current'): array
    {
        self::validateRecords210($records);

        $catalog = new SQLitePragmaSchemaCatalog($records);
        $rows = [];
        foreach ($records as $record) {
            if ($record->type !== 'table') {
                continue;
            }

            $tableInfo = self::tableInfoByName210($catalog, $record->name);
            $groups = [];
            foreach ($catalog->foreignKeyList($record->name) as $row) {
