        $notNull = (int) ($column['notnull'] ?? 0) === 1;
        $default = $column['dflt_value'] ?? null;

        if ($action === 'SET NULL') {
            return $notNull ? 'set_null_notnull_child' : 'ok';
        }
        if ($default === null || trim((string) $default) === '') {
            return 'set_default_missing_child_default';
