    public static function permutedParentUniqueRows219(array $records, string $phase = 'current'): array
    {
        self::validateRecords219($records);

        $catalog = new SQLitePragmaSchemaCatalog($records);
        $rows = [];
        foreach (self::groupForeignKeyRows219(self::foreignKeyListRows175($records, $phase)) as $group) {
            $parent = (string) $group[0]['parent'];
            $parentColumns = array_map(static fn (array $row): string => (string) $row['to'], $group);
            if (in_array('', $parentColumns, true)) {
                continue;
            }

            $candidate = self::permutedUniqueCandidate219($catalog, $parent, $parentColumns);
            if ($candidate === null) {
