            if ($record->type !== 'table' || $record->sql === null) {
                continue;
            }
            $body = self::parenthesizedBody220($record->sql);
            if ($body === null) {
                continue;
            }
            foreach (self::splitTopLevel220($body) as $definition) {
                $definition = trim($definition);
                if ($definition === '' || preg_match('/^(CONSTRAINT|PRIMARY|UNIQUE|CHECK|FOREIGN)\b/i', $definition) === 1) {
                    continue;
                }
                if (preg_match('/^(?<name>"(?:""|[^"])*"|`[^`]*`|\[[^\]]+\]|[A-Za-z_][A-Za-z0-9_]*)\b(?<rest>.*)$/s', $definition, $matches) !== 1) {
                    continue;
                }
                $collations[strtolower($record->name)][strtolower(self::normalizeIdentifier220($matches['name']))] = self::collationFromColumnDefinition220($matches['rest']);
            }
        }

        return $collations;
    }

    private static function collationFromColumnDefinition220(string $definition): string
    {
        if (preg_match('/\bCOLLATE\s+(?<coll>"(?:""|[^"])*"|`[^`]*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*)/i', $definition, $matches) !== 1) {
            return 'BINARY';
        }

        return strtoupper(self::normalizeIdentifier220($matches['coll']));
    }

    private static function parenthesizedBody220(string $sql): ?string
    {
        $start = strpos($sql, '(');
        if ($start === false) {
            return null;
        }

        $depth = 0;
        $quote = null;
        $length = strlen($sql);
        for ($i = $start; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if ($quote === "'" && ($sql[$i + 1] ?? '') === "'") {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return substr($sql, $start + 1, $i - $start - 1);
                }
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel220(string $sql): array
    {
        $parts = [];
        $start = 0;
        $depth = 0;
        $quote = null;
        $length = strlen($sql);
        for ($i = 0; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if ($quote === "'" && ($sql[$i + 1] ?? '') === "'") {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                continue;
            }
            if ($char === ',' && $depth === 0) {
                $parts[] = substr($sql, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $parts[] = substr($sql, $start);

        return $parts;
    }

    private static function normalizeIdentifier220(string $identifier): string
    {
        $identifier = trim($identifier);
        if ($identifier === '') {
            return '';
        }
        $first = $identifier[0];
        $last = $identifier[strlen($identifier) - 1];
        if (($first === '"' && $last === '"') || ($first === '`' && $last === '`') || ($first === '[' && $last === ']')) {
            return str_replace('""', '"', substr($identifier, 1, -1));
        }

        return $identifier;
    }

    /**
     * @param list<array<string,mixed>> $rows
     * @return list<list<array<string,mixed>>>
