     * @return array{rows:int,ok:int,mismatch:int,blocked:int,binary:int,nocase:int,rtrim:int,missing_parent_unique_index:int}
     */
    private static function collationCounts220(array $rows): array
    {
        $counts = [
            'rows' => count($rows),
            'ok' => 0,
            'mismatch' => 0,
            'blocked' => 0,
            'binary' => 0,
            'nocase' => 0,
            'rtrim' => 0,
            'missing_parent_unique_index' => 0,
        ];
        foreach ($rows as $row) {
            $status = (string) ($row['status'] ?? '');
            if ($status === 'ok') {
                $counts['ok']++;
            } elseif ($status === 'parent_collation_mismatch') {
                $counts['mismatch']++;
            } else {
                $counts['blocked']++;
                if (isset($counts[$status])) {
                    $counts[$status]++;
