     * @return array{rows:int,default_match:int,custom_match:int,composite_columns:int}
     */
    private static function matchCounts223(array $rows): array
    {
        $counts = [
            'rows' => count($rows),
            'default_match' => 0,
            'custom_match' => 0,
            'composite_columns' => 0,
        ];
        foreach ($rows as $row) {
            if (($row['status'] ?? null) === 'custom_match_name') {
                $counts['custom_match']++;
            } else {
                $counts['default_match']++;
            }
            if ((int) ($row['seq'] ?? 0) > 0) {
                $counts['composite_columns']++;
            }
        }

        return $counts;
    }

    /**
