        foreach ($rows as $row) {
            $status = (string) ($row['status'] ?? '');
            if ($status === 'ok') {
                $counts['ok']++;
            } else {
                $counts['blocked']++;
                if (isset($counts[$status])) {
                    $counts[$status]++;
                }
            }
            $counts['mismatch_columns'] += count((array) ($row['mismatch_columns'] ?? []));
        }

        return $counts;
