        return $summary;
    }

    private static function declaredCollation224(string $tail): string
    {
        if (preg_match('/\bCOLLATE\s+(?:"(?<dq>(?:""|[^"])*)"|`(?<bt>[^`]*)`|\[(?<br>[^\]]*)\]|(?<id>[A-Za-z_][A-Za-z0-9_]*))/i', $tail, $matches) !== 1) {
            return 'BINARY';
        }

        foreach (['dq', 'bt', 'br', 'id'] as $key) {
            if (($matches[$key] ?? '') !== '') {
                return strtoupper(str_replace('""', '"', (string) $matches[$key]));
            }
        }

        return 'BINARY';
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel224(string $value, string $separator): array
    {
        $parts = [];
        $start = 0;
        $depth = 0;
        $quote = null;
        $length = strlen($value);
        for ($i = 0; $i < $length; $i++) {
            $char = $value[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if ($quote === "'" && ($value[$i + 1] ?? null) === "'") {
                        $i++;
                        continue;
                    }
                    if ($quote === '"' && ($value[$i + 1] ?? null) === '"') {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')' && $depth > 0) {
                $depth--;
                continue;
            }
            if ($char === $separator && $depth === 0) {
                $parts[] = substr($value, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $parts[] = substr($value, $start);

        return $parts;
    }

    private static function parenthesizedBody224(string $sql): ?string
    {
        $open = strpos($sql, '(');
        if ($open === false) {
            return null;
        }

        $depth = 0;
        $quote = null;
        $length = strlen($sql);
        for ($i = $open; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                if ($char === $quote) {
                    if (($quote === "'" || $quote === '"') && ($sql[$i + 1] ?? null) === $quote) {
                        $i++;
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                continue;
            }
            if ($char === '[') {
                $quote = ']';
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return substr($sql, $open + 1, $i - $open - 1);
                }
            }
        }

        return null;
    }

    /**
     * @return array{identifier:string,end:int}|null
     */
    private static function readIdentifier224(string $value, int $offset): ?array
    {
        $length = strlen($value);
        while ($offset < $length && ctype_space($value[$offset])) {
            $offset++;
        }
        if ($offset >= $length) {
            return null;
        }

        $char = $value[$offset];
        if ($char === '"' || $char === '`' || $char === '[') {
            $close = $char === '[' ? ']' : $char;
            $end = $offset + 1;
            $identifier = '';
            while ($end < $length) {
                if ($value[$end] === $close) {
                    if ($close === '"' && ($value[$end + 1] ?? null) === '"') {
                        $identifier .= '"';
                        $end += 2;
                        continue;
                    }

                    return ['identifier' => $identifier, 'end' => $end + 1];
                }
                $identifier .= $value[$end];
                $end++;
            }

            return null;
        }

        if (preg_match('/[A-Za-z_][A-Za-z0-9_]*/A', substr($value, $offset), $matches) !== 1) {
            return null;
        }

        return ['identifier' => $matches[0], 'end' => $offset + strlen($matches[0])];
    }

