                    $primaryKey,
                    array_keys($primaryKey),
                ),
                'index_columns' => $primaryKey,
                'index_key_count' => count($primaryKey),
                'extra_columns' => [],
            ];
        }

        $firstWider = null;
        $firstWiderRows = [];
        $firstWiderColumns = [];

