        return trim($term);
    }

    /**
     * @return list<string>
     */
    private static function splitTopLevel233(string $input, string $delimiter): array
    {
        $parts = [];
        $buffer = '';
        $depth = 0;
        $quote = null;
        $length = strlen($input);
        for ($i = 0; $i < $length; $i++) {
            $ch = $input[$i];
            if ($quote !== null) {
                $buffer .= $ch;
                if ($ch === $quote) {
                    if ($i + 1 < $length && $input[$i + 1] === $quote) {
                        $buffer .= $input[++$i];
                        continue;
                    }
                    $quote = null;
                }
                continue;
            }
            if ($ch === "'" || $ch === '"' || $ch === '`') {
                $quote = $ch;
                $buffer .= $ch;
                continue;
            }
            if ($ch === '[') {
                $quote = ']';
                $buffer .= $ch;
                continue;
            }
            if ($ch === '(') {
                $depth++;
            } elseif ($ch === ')') {
                $depth = max(0, $depth - 1);
            }
            if ($ch === $delimiter && $depth === 0) {
                $parts[] = trim($buffer);
                $buffer = '';
                continue;
            }
            $buffer .= $ch;
        }
        if (trim($buffer) !== '') {
            $parts[] = trim($buffer);
        }

        return $parts;
    }

