    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return array<string,true>
     */
    private static function omittedParentColumnForeignKeys240(array $records): array
    {
        $omitted = [];
        foreach ($records as $record) {
            if ($record->type !== 'table' || $record->sql === null) {
                continue;
            }

            $id = 0;
            $body = self::parenthesizedBody240($record->sql);
            if ($body === null) {
                continue;
            }

            foreach (self::splitTopLevel240($body) as $definition) {
                $definition = trim($definition);
                if ($definition === '') {
                    continue;
                }

                if (preg_match('/^(?:CONSTRAINT\s+(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]+\]|[A-Za-z_][A-Za-z0-9_]*)\s+)?FOREIGN\s+KEY\s*\((?<from>[^)]*)\)\s+REFERENCES\s+(?<parent>"(?:""|[^"])*"|`[^`]*`|\[[^\]]+\]|[A-Za-z_][A-Za-z0-9_]*)(?<tail>.*)$/is', $definition, $matches) === 1) {
                    if (!self::referenceTailHasColumnList240($matches['tail'])) {
                        $omitted[strtolower($record->name) . '#' . $id] = true;
                    }
                    $id++;
                    continue;
                }

                if (preg_match('/^(?:"(?:""|[^"])*"|`[^`]*`|\[[^\]]+\]|[A-Za-z_][A-Za-z0-9_]*)\b(?<tail>.*)$/s', $definition, $matches) !== 1) {
