    private static function derivedForeignKeyRows241(array $records, string $phase): array
    {
        $rows = [];
        try {
            $derivedRows = self::foreignKeyListRows175($records, $phase);
        } catch (InvalidArgumentException) {
            $derivedRows = [];
        }

        foreach ($derivedRows as $row) {
            $rows[self::fkKey241((string) $row['table'], (int) $row['id'], (int) $row['seq'])] = $row;
        }

        return $rows;
    }

    /**
     * @param list<SQLiteSchemaRecord> $records
     * @return array<string,list<string>>
     */
    private static function primaryKeys241(SQLitePragmaSchemaCatalog $catalog, array $records): array
    {
        $primaryKeys = [];
        foreach ($records as $record) {
            if ($record->type !== 'table') {
                continue;
            }

            $columns = [];
            foreach ($catalog->tableInfo($record->name) as $row) {
                $pk = (int) ($row['pk'] ?? 0);
                if ($pk > 0) {
                    $columns[$pk] = (string) $row['name'];
                }
            }
            ksort($columns);
            $primaryKeys[strtolower($record->name)] = array_values($columns);
        }

        return $primaryKeys;
    }

    /**
