     */
    private static function rowidCounts242(array $rows): array
    {
        $counts = [
            'rows' => count($rows),
            'rowid_alias_parent_key' => 0,
            'ok_declared_parent_column' => 0,
            'rowid_auxiliary_indexes' => 0,
            'rowid_auxiliary_rows' => 0,
