        $columns = [];
        $indexes = [];
        foreach ($rows as $row) {
            $status = (string) ($row['status'] ?? '');
            if (array_key_exists($status, $counts)) {
                $counts[$status]++;
            }
            $columns[strtolower((string) ($row['to'] ?? ''))] = true;
            if (($row['parent_unique_index'] ?? null) !== null) {
                $indexes[(string) $row['parent_unique_index']] = true;
            }
