                    'parent_index_origin' => $candidate['origin'],
                    'parent_index_columns' => $candidate['columns'],
                    'parent_index_collations' => $candidate['collations'],
                    'parent_notnull' => $notNull,
                    'parent_pk' => (int) ($parentColumn['pk'] ?? 0),
                    'status' => $status,
